create type public.app_role as enum ('admin');
create table public.user_roles (id uuid primary key default gen_random_uuid(), user_id uuid references auth.users(id) on delete cascade not null, role app_role not null, unique(user_id, role));
grant select on public.user_roles to authenticated;
grant all on public.user_roles to service_role;
alter table public.user_roles enable row level security;
create or replace function public.has_role(_user_id uuid, _role app_role) returns boolean language sql stable security definer set search_path = public as $$ select exists (select 1 from public.user_roles where user_id=_user_id and role=_role) $$;
create policy "own roles" on public.user_roles for select to authenticated using (user_id = auth.uid());

create or replace function public.make_first_admin() returns trigger language plpgsql security definer set search_path = public as $$
begin
  if not exists (select 1 from public.user_roles where role='admin') then
    insert into public.user_roles(user_id, role) values (new.id, 'admin');
  end if;
  return new;
end $$;
create trigger on_auth_user_created_admin after insert on auth.users for each row execute function public.make_first_admin();

create table public.products (
  id uuid primary key default gen_random_uuid(),
  categoria text not null, nome text not null, descricao text not null default '',
  preco numeric(10,2), preco_p2 numeric(10,2), preco_p4 numeric(10,2),
  imagem_url text, ordem int not null default 0, ativo boolean not null default true,
  created_at timestamptz not null default now()
);
grant select on public.products to anon, authenticated;
grant insert, update, delete on public.products to authenticated;
grant all on public.products to service_role;
alter table public.products enable row level security;
create policy "public read active" on public.products for select using (ativo or public.has_role(auth.uid(),'admin'));
create policy "admin insert" on public.products for insert to authenticated with check (public.has_role(auth.uid(),'admin'));
create policy "admin update" on public.products for update to authenticated using (public.has_role(auth.uid(),'admin'));
create policy "admin delete" on public.products for delete to authenticated using (public.has_role(auth.uid(),'admin'));

create table public.gallery_photos (
  id uuid primary key default gen_random_uuid(),
  url text not null, alt text not null default '', ordem int not null default 0,
  created_at timestamptz not null default now()
);
grant select on public.gallery_photos to anon, authenticated;
grant insert, update, delete on public.gallery_photos to authenticated;
grant all on public.gallery_photos to service_role;
alter table public.gallery_photos enable row level security;
create policy "public read" on public.gallery_photos for select using (true);
create policy "admin insert" on public.gallery_photos for insert to authenticated with check (public.has_role(auth.uid(),'admin'));
create policy "admin update" on public.gallery_photos for update to authenticated using (public.has_role(auth.uid(),'admin'));
create policy "admin delete" on public.gallery_photos for delete to authenticated using (public.has_role(auth.uid(),'admin'));

